
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_15_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_15", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.049947578113147e+00, -4.949980463071686e+00, -4.809821249603269e+00, -4.615475705008505e+00, -4.350188858140973e+00, -3.995903336747735e+00, -3.536571376586056e+00, -2.963103212612091e+00, -2.279149708697818e+00, -1.532071433058108e+00, -9.171883511543671e-01, -6.532229623370797e-01, -6.261953871282194e-01, -5.362741963827746e-01, -3.677597467516084e-01, -2.038769151935081e-01, -9.010462498540923e-02, -2.986676936898268e-02, -6.407931991180726e-03, -7.207442977338003e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


